// Encyclopédie des espèces : ce qu'on découvre en touchant les petites icônes de la fiche d'une carte.
// Pour chaque espèce : son régime et son menu, son rythme (jour ou nuit), sa vie de groupe, ses petits,
// sa vitesse de pointe quand elle est connue, son statut sur la Liste rouge de l'UICN, ce qui la menace,
// et une anecdote de plus. Valeurs typiques et arrondies, comme les mesures des cartes.
// Statuts UICN vérifiés avec Wikidata (scripts/fiches/wikidata.json, robot « Fiches des espèces »).
// Pour une sous-espèce, une race ou un groupe d'espèces, le statut est celui de l'espèce (ou « non évalué »),
// et la note précise le cas.

export type RegimeId =
  | 'carnivore'
  | 'piscivore'
  | 'insectivore'
  | 'herbivore'
  | 'frugivore'
  | 'nectarivore'
  | 'omnivore'
  | 'charognard'
  | 'filtreur'
  | 'hematophage'
  | 'recycleur';

export const REGIMES: Record<RegimeId, string> = {
  carnivore: 'Carnivore',
  piscivore: 'Mangeur de poissons',
  insectivore: 'Mangeur d’insectes',
  herbivore: 'Herbivore',
  frugivore: 'Mangeur de fruits',
  nectarivore: 'Buveur de nectar',
  omnivore: 'Omnivore',
  charognard: 'Charognard',
  filtreur: 'Mangeur de plancton',
  hematophage: 'Buveur de sang',
  recycleur: 'Recycleur de matière morte',
};

/** Moment de la journée où l'animal est actif. */
export type Rythme = 'jour' | 'nuit' | 'crepuscule' | 'jour-nuit';

export const RYTHMES: Record<Rythme, string> = {
  jour: 'Actif le jour',
  nuit: 'Actif la nuit',
  crepuscule: 'Actif à l’aube et au crépuscule',
  'jour-nuit': 'Actif de jour comme de nuit',
};

/** Catégories de la Liste rouge de l'UICN, plus les animaux domestiques et les groupes d'espèces (statuts variés). */
export type Uicn = 'LC' | 'NT' | 'VU' | 'EN' | 'CR' | 'EW' | 'EX' | 'DD' | 'NE' | 'DOM' | 'GRP';

export const UICN: Record<Uicn, { label: string; short: string }> = {
  LC: { label: 'Préoccupation mineure', short: 'LC' },
  NT: { label: 'Quasi menacée', short: 'NT' },
  VU: { label: 'Vulnérable', short: 'VU' },
  EN: { label: 'En danger', short: 'EN' },
  CR: { label: 'En danger critique', short: 'CR' },
  EW: { label: 'Éteinte à l’état sauvage', short: 'EW' },
  EX: { label: 'Éteinte', short: 'EX' },
  DD: { label: 'Données insuffisantes', short: 'DD' },
  NE: { label: 'Non évaluée', short: 'NE' },
  DOM: { label: 'Animal domestique', short: 'DOM' },
  GRP: { label: 'Plusieurs espèces', short: '—' },
};

/** L'échelle de la Liste rouge, de la moins à la plus grave. */
export const UICN_ECHELLE: Uicn[] = ['LC', 'NT', 'VU', 'EN', 'CR', 'EW', 'EX'];

export interface Encyclo {
  regime: RegimeId;
  /** ce qu'il mange */
  menu: string;
  rythme: Rythme;
  /** vie de groupe */
  social: string;
  /** gestation ou incubation, nombre de petits */
  petits: string;
  uicn: Uicn;
  /** une anecdote de plus que celle de la carte */
  savais: string;
  /** vitesse de pointe en km/h, et dans quelles conditions */
  vitesse?: { kmh: number; note?: string };
  /** ce qui la menace (ou l'a fait disparaître) */
  menaces?: string;
  /** précision sur le statut (sous-espèce, race, groupe d'espèces) */
  note?: string;
}

type Extra = Pick<Encyclo, 'vitesse' | 'menaces' | 'note'>;

function f(regime: RegimeId, menu: string, rythme: Rythme, social: string, petits: string, uicn: Uicn, savais: string, extra: Partial<Extra> = {}): Encyclo {
  return { regime, menu, rythme, social, petits, uicn, savais, ...extra };
}

/** Vitesse de pointe. */
const V = (kmh: number, note?: string) => ({ vitesse: note ? { kmh, note } : { kmh } });
/** Menaces. */
const M = (menaces: string) => ({ menaces });
/** Note sur le statut. */
const N = (note: string) => ({ note });

